export const CelebrationsHtml = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover\" />\n<title>Celebrations — Church App Prototype</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,300;9..144,450;9..144,560;9..144,650&family=Inter:wght@400;500;600;700&family=Cormorant+Garamond:ital@1&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --ivory:#FBF7EF;\n  --ivory-deep:#F1E9D8;\n  --paper:#FFFFFF;\n  --ink:#1B2242;\n  --ink-soft:#5B6280;\n  --royal:#1E2A63;\n  --royal-light:#37469B;\n  --royal-glow:rgba(55,70,155,0.30);\n  --gold:#BE9A3A;\n  --gold-light:#E7C767;\n  --gold-soft:rgba(190,154,58,0.16);\n  --line:rgba(27,34,66,0.09);\n  --radius-xl:30px;\n  --radius-lg:22px;\n  --radius-md:16px;\n  --radius-sm:10px;\n  --shadow-soft:0 10px 30px rgba(30,42,99,0.10);\n  --shadow-card:0 6px 20px rgba(30,42,99,0.08);\n}\n*{box-sizing:border-box;}\nhtml,body{margin:0;padding:0;}\nbody{\n  font-family:'Inter',sans-serif;\n  background:\n    radial-gradient(circle at 20% 10%, rgba(190,154,58,0.10), transparent 45%),\n    radial-gradient(circle at 85% 85%, rgba(55,70,155,0.10), transparent 45%),\n    var(--ivory-deep);\n  min-height:100vh;\n  display:flex;\n  align-items:center;\n  justify-content:center;\n  padding:32px 12px;\n  color:var(--ink);\n}\n.stage{ position: relative; width: 100%; height: 100%; overflow: hidden; display: flex; flex-direction: column; }\n.rosette-bg{\n  position:absolute;\n  inset:-60px;\n  opacity:0.06;\n  z-index:0;\n  pointer-events:none;\n}\n.phone{ position: relative; width: 100%; height: 100%; overflow: hidden; display: flex; flex-direction: column; background: var(--ivory); }\n.statusbar{ display: none; }\n.notch{ display: none; }\n.appbar{\n  flex:0 0 auto;\n  display:flex;\n  align-items:center;\n  gap:12px;\n  padding:2px 18px 14px 18px;\n  position:relative;\n}\n.appbar .back-btn{\n  width:36px;height:36px;\n  border-radius:50%;\n  background:var(--paper);\n  border:1px solid var(--line);\n  display:flex;align-items:center;justify-content:center;\n  cursor:pointer;\n  box-shadow:var(--shadow-card);\n  flex:0 0 auto;\n  transition:transform .15s ease;\n}\n.appbar .back-btn:active{transform:scale(0.9);}\n.appbar .back-btn svg{width:16px;height:16px;stroke:var(--royal);}\n.appbar .back-btn.hidden{visibility:hidden;}\n.appbar h1{\n  font-family:'Fraunces',serif;\n  font-weight:560;\n  font-size:19px;\n  letter-spacing:0.2px;\n  margin:0;\n  flex:1;\n  color:var(--royal);\n}\n.appbar .eyebrow{\n  font-family:'Inter';\n  font-size:10.5px;\n  letter-spacing:1.6px;\n  text-transform:uppercase;\n  color:var(--gold);\n  font-weight:700;\n  display:block;\n  margin-bottom:2px;\n}\n.screen-root{\n  flex:1 1 auto;\n  overflow-y:auto;\n  overflow-x:hidden;\n  -ms-overflow-style:none;\n  scrollbar-width:none;\n  position:relative;\n}\n.screen-root::-webkit-scrollbar{display:none;}\n.screen{\n  padding:2px 18px 100px 18px;\n  animation:screenIn .32s cubic-bezier(.2,.8,.2,1);\n}\n@keyframes screenIn{\n  from{opacity:0; transform:translateY(10px);}\n  to{opacity:1; transform:translateY(0);}\n}\n@media (prefers-reduced-motion: reduce){\n  .screen{animation:none;}\n  *{transition:none !important;}\n}\n\n/* ---------- Rose window motif ---------- */\n.rose-icon-frame{\n  width:56px;height:56px;\n  border-radius:50%;\n  display:flex;align-items:center;justify-content:center;\n  position:relative;\n  flex:0 0 auto;\n}\n.rose-icon-frame svg.rose-bg{position:absolute;inset:0;width:100%;height:100%;opacity:0.5;}\n.rose-icon-frame .glyph{position:relative;z-index:2;width:26px;height:26px;}\n\n/* ---------- Dashboard ---------- */\n.hero-card{\n  border-radius:var(--radius-xl);\n  padding:26px 22px 24px 22px;\n  background:linear-gradient(150deg, var(--royal) 0%, #2B3A80 55%, var(--royal-light) 100%);\n  color:#fff;\n  position:relative;\n  overflow:hidden;\n  box-shadow:0 16px 34px rgba(30,42,99,0.30);\n  margin-top:6px;\n}\n.hero-card::after{\n  content:\"\";\n  position:absolute; right:-40px; top:-40px;\n  width:180px;height:180px;\n  background:radial-gradient(circle, rgba(231,199,103,0.35), transparent 70%);\n}\n.hero-eyebrow{\n  font-size:10.5px; letter-spacing:2px; text-transform:uppercase;\n  color:var(--gold-light); font-weight:700; margin-bottom:8px;\n}\n.hero-title{\n  font-family:'Fraunces',serif; font-weight:650; font-size:26px; line-height:1.15;\n  margin:0 0 6px 0;\n}\n.hero-sub{\n  font-size:13px; color:rgba(255,255,255,0.78); line-height:1.5; max-width:280px;\n}\n.hero-stats{\n  display:flex; gap:18px; margin-top:18px; position:relative; z-index:2;\n}\n.hero-stat b{display:block; font-family:'Fraunces',serif; font-size:22px; font-weight:650;}\n.hero-stat span{font-size:10.5px; color:rgba(255,255,255,0.7); letter-spacing:0.5px;}\n\n.section-label{\n  font-size:11px; letter-spacing:1.6px; text-transform:uppercase;\n  color:var(--ink-soft); font-weight:700; margin:26px 2px 12px 2px;\n}\n.cat-grid{\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:14px;\n}\n.cat-card{\n  border-radius:var(--radius-lg);\n  padding:18px 16px 16px 16px;\n  cursor:pointer;\n  position:relative;\n  overflow:hidden;\n  background:rgba(255,255,255,0.55);\n  backdrop-filter:blur(14px);\n  border:1px solid rgba(255,255,255,0.6);\n  box-shadow:var(--shadow-card);\n  transition:transform .18s ease, box-shadow .18s ease;\n}\n.cat-card:active{transform:scale(0.96);}\n.cat-card:hover{transform:translateY(-3px); box-shadow:0 14px 30px rgba(30,42,99,0.16);}\n.cat-card .tint{\n  position:absolute; inset:0; opacity:0.5; z-index:0;\n}\n.cat-card .content{position:relative; z-index:1;}\n.cat-card .rose-icon-frame{margin-bottom:14px;}\n.cat-card .cat-name{\n  font-family:'Fraunces',serif; font-weight:560; font-size:15.5px; color:var(--ink);\n  margin:0 0 4px 0;\n}\n.cat-card .cat-count{\n  font-size:11.5px; color:var(--ink-soft); font-weight:500;\n}\n.cat-card .cat-count b{color:var(--royal); font-weight:700;}\n\n/* ---------- Filter tabs ---------- */\n.filter-scroll{\n  display:flex; gap:8px; overflow-x:auto; padding:4px 0 14px 0;\n  -ms-overflow-style:none; scrollbar-width:none;\n}\n.filter-scroll::-webkit-scrollbar{display:none;}\n.filter-chip{\n  flex:0 0 auto;\n  padding:9px 16px;\n  border-radius:999px;\n  font-size:12.5px; font-weight:600;\n  background:var(--paper);\n  border:1px solid var(--line);\n  color:var(--ink-soft);\n  cursor:pointer;\n  white-space:nowrap;\n  transition:all .15s ease;\n}\n.filter-chip.active{\n  background:linear-gradient(120deg, var(--royal), var(--royal-light));\n  color:#fff;\n  border-color:transparent;\n  box-shadow:0 6px 16px rgba(30,42,99,0.25);\n}\n\n.search-row{\n  display:flex; gap:8px; align-items:center; margin-bottom:10px;\n}\n.search-box{\n  flex:1;\n  display:flex; align-items:center; gap:8px;\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:var(--radius-md);\n  padding:11px 14px;\n}\n.search-box svg{width:16px;height:16px; stroke:var(--ink-soft); flex:0 0 auto;}\n.search-box input{\n  border:none; outline:none; font-size:13.5px; font-family:'Inter'; width:100%;\n  background:transparent; color:var(--ink);\n}\n.icon-btn{\n  width:40px;height:40px; border-radius:var(--radius-md);\n  background:var(--paper); border:1px solid var(--line);\n  display:flex; align-items:center; justify-content:center; cursor:pointer;\n  flex:0 0 auto; position:relative;\n}\n.icon-btn svg{width:17px;height:17px; stroke:var(--royal);}\n.icon-btn.active-dot::after{\n  content:\"\"; position:absolute; top:7px; right:7px; width:7px; height:7px; border-radius:50%;\n  background:var(--gold);\n}\n\n.filters-panel{\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:var(--radius-lg);\n  padding:14px;\n  margin-bottom:14px;\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:10px;\n  animation:screenIn .25s ease;\n}\n.filters-panel .field{grid-column:span 1;}\n.filters-panel .field.full{grid-column:span 2;}\n.filters-panel label{\n  display:block; font-size:10px; letter-spacing:1px; text-transform:uppercase;\n  color:var(--ink-soft); font-weight:700; margin-bottom:5px;\n}\n.filters-panel select{\n  width:100%; padding:9px 10px; border-radius:var(--radius-sm);\n  border:1px solid var(--line); background:var(--ivory); font-size:12.5px; color:var(--ink);\n  font-family:'Inter';\n}\n.result-count{\n  font-size:12px; color:var(--ink-soft); margin:2px 2px 12px 2px;\n}\n\n/* ---------- Member card ---------- */\n.member-card{\n  display:flex; align-items:center; gap:12px;\n  background:rgba(255,255,255,0.7);\n  backdrop-filter:blur(10px);\n  border:1px solid rgba(255,255,255,0.7);\n  border-radius:var(--radius-lg);\n  padding:12px 12px;\n  margin-bottom:10px;\n  cursor:pointer;\n  box-shadow:var(--shadow-card);\n  transition:transform .15s ease, box-shadow .15s ease;\n}\n.member-card:active{transform:scale(0.97);}\n.member-card:hover{box-shadow:0 12px 24px rgba(30,42,99,0.14); transform:translateY(-2px);}\n.avatar{\n  width:52px;height:52px;border-radius:50%;\n  display:flex;align-items:center;justify-content:center;\n  color:#fff; font-family:'Fraunces',serif; font-weight:650; font-size:16px;\n  flex:0 0 auto;\n  box-shadow:inset 0 0 0 3px rgba(255,255,255,0.5);\n}\n.avatar.lg{width:96px;height:96px;font-size:30px; box-shadow:0 10px 26px rgba(30,42,99,0.25), inset 0 0 0 4px rgba(255,255,255,0.6);}\n.mc-info{flex:1; min-width:0;}\n.mc-name{font-family:'Fraunces',serif; font-weight:560; font-size:15px; color:var(--ink); margin:0 0 3px 0;}\n.mc-meta{font-size:11.5px; color:var(--ink-soft); display:flex; align-items:center; gap:6px; flex-wrap:wrap;}\n.badge{\n  font-size:9.5px; font-weight:700; letter-spacing:0.4px; text-transform:uppercase;\n  padding:3px 8px; border-radius:999px; color:#fff;\n}\n.mc-date{font-size:11px; color:var(--gold); font-weight:700;}\n.mc-actions{display:flex; flex-direction:column; gap:6px; flex:0 0 auto;}\n.mini-btn{\n  width:34px;height:34px;border-radius:50%;\n  display:flex;align-items:center;justify-content:center; cursor:pointer;\n  border:1px solid var(--line); background:var(--paper);\n}\n.mini-btn svg{width:15px;height:15px;}\n.mini-btn.whatsapp svg{stroke:#25D366; fill:#25D366;}\n.mini-btn.wish svg{stroke:var(--gold);}\n\n.empty-state{\n  text-align:center; padding:60px 20px 20px 20px; color:var(--ink-soft);\n}\n.empty-state svg{width:56px;height:56px; stroke:var(--gold); margin-bottom:14px; opacity:0.7;}\n.empty-state p{font-size:13px; line-height:1.5; margin:0;}\n\n/* ---------- Details screen ---------- */\n.details-hero{\n  text-align:center; padding:16px 0 6px 0;\n}\n.details-hero .avatar.lg{margin:0 auto 14px auto;}\n.details-hero h2{\n  font-family:'Fraunces',serif; font-weight:650; font-size:22px; margin:0 0 4px 0; color:var(--ink);\n}\n.details-hero .cat-tag{\n  display:inline-block; font-size:11px; font-weight:700; letter-spacing:0.5px;\n  padding:5px 14px; border-radius:999px; color:#fff; margin-bottom:4px;\n}\n.info-grid{\n  display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-top:20px;\n}\n.info-tile{\n  background:var(--paper); border:1px solid var(--line); border-radius:var(--radius-md);\n  padding:13px 14px;\n}\n.info-tile .lbl{font-size:10px; letter-spacing:1px; text-transform:uppercase; color:var(--ink-soft); font-weight:700; margin-bottom:5px;}\n.info-tile .val{font-size:14px; font-weight:600; color:var(--ink); font-family:'Fraunces',serif;}\n.info-tile.full{grid-column:span 2;}\n\n.primary-btn{\n  display:flex; align-items:center; justify-content:center; gap:8px;\n  width:100%; padding:15px; border-radius:var(--radius-md); border:none; cursor:pointer;\n  font-family:'Inter'; font-weight:700; font-size:14px; letter-spacing:0.2px;\n  background:linear-gradient(120deg, var(--gold), var(--gold-light));\n  color:#3a2c05;\n  box-shadow:0 10px 24px rgba(190,154,58,0.35);\n  margin-top:22px;\n  transition:transform .15s ease;\n}\n.primary-btn:active{transform:scale(0.97);}\n.primary-btn.royal{\n  background:linear-gradient(120deg, var(--royal), var(--royal-light));\n  color:#fff; box-shadow:0 10px 24px rgba(30,42,99,0.30);\n}\n.primary-btn.outline{\n  background:transparent; border:1.5px solid var(--royal); color:var(--royal); box-shadow:none;\n}\n.primary-btn svg{width:16px;height:16px;}\n.secondary-row{display:flex; gap:10px; margin-top:10px;}\n.secondary-row .primary-btn{margin-top:0;}\n\n/* ---------- Theme selection ---------- */\n.theme-grid{\n  display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-top:8px;\n}\n.theme-card{\n  border-radius:var(--radius-lg); overflow:hidden; cursor:pointer; position:relative;\n  border:2px solid transparent; box-shadow:var(--shadow-card);\n  transition:transform .15s ease;\n}\n.theme-card:active{transform:scale(0.96);}\n.theme-card.selected{border-color:var(--gold); box-shadow:0 0 0 3px var(--gold-soft);}\n.theme-preview{height:96px; position:relative;}\n.theme-preview svg{width:100%;height:100%;}\n.theme-label{\n  padding:9px 10px; background:var(--paper); font-size:12px; font-weight:600; color:var(--ink);\n  font-family:'Fraunces',serif;\n}\n.theme-check{\n  position:absolute; top:8px; right:8px; width:22px;height:22px; border-radius:50%;\n  background:var(--gold); display:flex; align-items:center; justify-content:center;\n  box-shadow:0 4px 10px rgba(0,0,0,0.2);\n}\n.theme-check svg{width:12px;height:12px; stroke:#fff; stroke-width:3;}\n\n/* ---------- Customize screen ---------- */\n.option-row{\n  display:flex; align-items:center; justify-content:space-between; gap:10px;\n  background:var(--paper); border:1px solid var(--line); border-radius:var(--radius-md);\n  padding:14px; margin-bottom:10px; cursor:pointer;\n  transition:box-shadow .15s ease;\n}\n.option-row:hover{box-shadow:var(--shadow-card);}\n.option-row .left{display:flex; align-items:center; gap:12px;}\n.option-row .ic{\n  width:38px;height:38px;border-radius:12px; display:flex;align-items:center;justify-content:center;\n  background:var(--gold-soft);\n}\n.option-row .ic svg{width:18px;height:18px; stroke:var(--gold);}\n.option-row .txt .t1{font-size:13.5px; font-weight:650; color:var(--ink); font-family:'Fraunces',serif;}\n.option-row .txt .t2{font-size:11.5px; color:var(--ink-soft); margin-top:2px;}\n.chevron svg{width:15px;height:15px; stroke:var(--ink-soft);}\n\ntextarea.msg-input{\n  width:100%; border:1px solid var(--line); border-radius:var(--radius-md); padding:12px 14px;\n  font-family:'Inter'; font-size:13.5px; color:var(--ink); resize:vertical; min-height:88px;\n  background:var(--paper); line-height:1.5;\n}\n\n/* ---------- Verse screen ---------- */\n.verse-card{\n  background:var(--paper); border:1px solid var(--line); border-radius:var(--radius-lg);\n  padding:16px; margin-bottom:12px; cursor:pointer; position:relative;\n  border-left:4px solid var(--gold-light);\n  transition:box-shadow .15s ease, transform .15s ease;\n}\n.verse-card:hover{transform:translateX(2px); box-shadow:var(--shadow-card);}\n.verse-card.selected{border-left-color:var(--royal); background:linear-gradient(180deg, rgba(55,70,155,0.06), transparent);}\n.verse-text{\n  font-family:'Cormorant Garamond', serif; font-style:italic; font-size:15.5px; line-height:1.5; color:var(--ink);\n  margin:0 0 8px 0;\n}\n.verse-ref{font-size:11.5px; font-weight:700; color:var(--royal); letter-spacing:0.3px;}\n\n/* ---------- Upload screen ---------- */\n.upload-zone{\n  border:2px dashed var(--line); border-radius:var(--radius-lg);\n  padding:38px 20px; text-align:center; cursor:pointer; margin-top:10px;\n  background:var(--paper);\n}\n.upload-zone svg{width:40px;height:40px; stroke:var(--gold); margin-bottom:10px;}\n.upload-zone p{font-size:13px; color:var(--ink-soft); margin:0;}\n.upload-zone .hint{font-size:11px; color:var(--ink-soft); opacity:0.7; margin-top:4px;}\n.sample-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin-top:16px;}\n.sample-thumb{\n  aspect-ratio:1; border-radius:var(--radius-sm); cursor:pointer; position:relative; overflow:hidden;\n  border:2px solid transparent;\n}\n.sample-thumb.selected{border-color:var(--gold);}\n.sample-thumb svg{width:100%;height:100%;}\n\n/* ---------- Greeting preview card ---------- */\n.greeting-frame{\n  border-radius:var(--radius-xl); overflow:hidden; box-shadow:0 18px 40px rgba(30,42,99,0.22);\n  margin-top:10px; position:relative;\n}\n.greeting-frame svg{width:100%; display:block;}\n.greeting-overlay{\n  position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center;\n  text-align:center; padding:26px; color:#fff;\n}\n.greeting-overlay .g-crest{font-size:10px; letter-spacing:2px; text-transform:uppercase; opacity:0.85; margin-bottom:10px;}\n.greeting-overlay .g-title{font-family:'Fraunces',serif; font-weight:650; font-size:22px; margin:0 0 8px 0;}\n.greeting-overlay .g-name{font-family:'Fraunces',serif; font-weight:560; font-size:17px; margin:0 0 12px 0;}\n.greeting-overlay .g-msg{font-size:12.5px; line-height:1.5; max-width:250px; margin:0 0 12px 0; opacity:0.95;}\n.greeting-overlay .g-verse{font-family:'Cormorant Garamond',serif; font-style:italic; font-size:13px; max-width:250px; opacity:0.9;}\n.greeting-overlay .g-sender{font-size:10.5px; margin-top:14px; opacity:0.75; letter-spacing:0.4px;}\n\n/* ---------- WhatsApp screen ---------- */\n.wa-header{\n  display:flex; align-items:center; gap:10px; background:#075E54; color:#fff;\n  padding:12px 14px; border-radius:var(--radius-md) var(--radius-md) 0 0; margin-top:8px;\n}\n.wa-header .avatar{width:36px;height:36px; font-size:13px;}\n.wa-header .nm{font-size:13.5px; font-weight:600;}\n.wa-header .st{font-size:10.5px; opacity:0.8;}\n.wa-body{\n  background:#E5DDD5; padding:16px 12px; border-radius:0 0 var(--radius-md) var(--radius-md);\n}\n.wa-bubble{\n  background:#fff; border-radius:10px; padding:8px; max-width:90%; margin-left:auto;\n  box-shadow:0 1px 2px rgba(0,0,0,0.15); margin-bottom:10px;\n}\n.wa-bubble img, .wa-bubble svg{width:100%; border-radius:6px; display:block;}\n.wa-bubble .wa-caption{padding:8px 4px 2px 4px; font-size:12.5px; color:#111; line-height:1.5;}\n.wa-bubble .wa-verse{font-style:italic; font-family:'Cormorant Garamond',serif; font-size:12.5px; color:#333; padding:2px 4px 4px 4px;}\n.wa-bubble .wa-time{font-size:10px; color:#8b8b8b; text-align:right; padding:2px 4px 0 0;}\n\n/* ---------- Confirm screen ---------- */\n.confirm-wrap{\n  display:flex; flex-direction:column; align-items:center; justify-content:center;\n  text-align:center; padding:70px 20px 20px 20px;\n}\n.confirm-check{\n  width:88px;height:88px; border-radius:50%;\n  background:linear-gradient(140deg, var(--gold), var(--gold-light));\n  display:flex; align-items:center; justify-content:center; margin-bottom:22px;\n  box-shadow:0 16px 32px rgba(190,154,58,0.35);\n  animation:pop .5s cubic-bezier(.2,1.4,.4,1);\n}\n@keyframes pop{from{transform:scale(0.4); opacity:0;} to{transform:scale(1); opacity:1;}}\n.confirm-check svg{width:40px;height:40px; stroke:#fff; stroke-width:3;}\n.confirm-wrap h2{font-family:'Fraunces',serif; font-size:21px; font-weight:650; margin:0 0 8px 0; color:var(--ink);}\n.confirm-wrap p{font-size:13.5px; color:var(--ink-soft); max-width:260px; line-height:1.5; margin:0 0 30px 0;}\n\n/* ---------- Skeleton ---------- */\n.skeleton{\n  background:linear-gradient(90deg, #ece5d5 25%, #f4efe2 37%, #ece5d5 63%);\n  background-size:400% 100%;\n  animation:shimmer 1.3s ease infinite;\n  border-radius:var(--radius-md);\n}\n@keyframes shimmer{0%{background-position:100% 0;} 100%{background-position:0 0;}}\n.skel-card{height:76px; margin-bottom:10px;}\n\n.toast{\n  position:absolute; bottom:26px; left:18px; right:18px;\n  background:var(--ink); color:#fff; padding:13px 16px; border-radius:var(--radius-md);\n  font-size:12.5px; text-align:center; box-shadow:0 12px 30px rgba(0,0,0,0.3);\n  z-index:50; opacity:0; pointer-events:none; transform:translateY(10px);\n  transition:all .25s ease;\n}\n.toast.show{opacity:1; transform:translateY(0);}\n\n.divider-label{\n  display:flex; align-items:center; gap:10px; margin:22px 2px 12px 2px;\n  color:var(--ink-soft); font-size:11px; letter-spacing:1.5px; text-transform:uppercase; font-weight:700;\n}\n.divider-label::after{content:\"\"; flex:1; height:1px; background:var(--line);}\n\n.footer-note{\n  text-align:center; font-size:10.5px; color:var(--ink-soft); opacity:0.7; margin-top:26px; letter-spacing:0.3px;\n}\n</style>\n</head>\n<body>\n\n<div class=\"stage\">\n  <svg class=\"rosette-bg\" viewBox=\"0 0 400 400\" xmlns=\"http://www.w3.org/2000/svg\">\n    <g fill=\"none\" stroke=\"#37469B\" stroke-width=\"1\">\n      <circle cx=\"200\" cy=\"200\" r=\"180\"/>\n      <circle cx=\"200\" cy=\"200\" r=\"130\"/>\n      <circle cx=\"200\" cy=\"200\" r=\"80\"/>\n      <g id=\"petals\"></g>\n    </g>\n  </svg>\n\n  <div class=\"phone\">\n    <div class=\"notch\"></div>\n    <div class=\"statusbar\">\n      <span id=\"clock\">9:41</span>\n      <span style=\"display:flex; gap:5px; align-items:center;\">\n        <svg width=\"16\" height=\"11\" viewBox=\"0 0 16 11\" fill=\"none\"><rect x=\"0\" y=\"6\" width=\"3\" height=\"5\" rx=\"0.5\" fill=\"#1B2242\"/><rect x=\"4.5\" y=\"4\" width=\"3\" height=\"7\" rx=\"0.5\" fill=\"#1B2242\"/><rect x=\"9\" y=\"2\" width=\"3\" height=\"9\" rx=\"0.5\" fill=\"#1B2242\"/><rect x=\"13.5\" y=\"0\" width=\"2.5\" height=\"11\" rx=\"0.5\" fill=\"#1B2242\" opacity=\"0.35\"/></svg>\n        <svg width=\"20\" height=\"11\" viewBox=\"0 0 20 11\" fill=\"none\"><rect x=\"0.5\" y=\"0.5\" width=\"17\" height=\"10\" rx=\"2.5\" stroke=\"#1B2242\"/><rect x=\"2\" y=\"2\" width=\"12\" height=\"7\" rx=\"1\" fill=\"#1B2242\"/><rect x=\"18.5\" y=\"3.5\" width=\"1.3\" height=\"4\" rx=\"0.6\" fill=\"#1B2242\"/></svg>\n      </span>\n    </div>\n\n    <div class=\"appbar\">\n      <div class=\"back-btn hidden\" id=\"backBtn\" data-action=\"back\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 19l-7-7 7-7\"/></svg>\n      </div>\n      <div>\n        <span class=\"eyebrow\" id=\"appEyebrow\">Church Companion</span>\n        <h1 id=\"appTitle\">Celebrations</h1>\n      </div>\n    </div>\n\n    <div class=\"screen-root\" id=\"screenRoot\"></div>\n    <div class=\"toast\" id=\"toast\"></div>\n  </div>\n</div>\n\n<script>\n/* ============================= DATA ============================= */\nconst TODAY = new Date(2026,6,11); // July 11, 2026\n\nconst CATEGORIES = [\n  { key:'birthday', label:'Birthday', icon:'cake',\n    grad:['#E7C767','#BE9A3A'], tint:'linear-gradient(150deg, rgba(231,199,103,0.35), rgba(190,154,58,0.10))' },\n  { key:'wedding', label:'Wedding Anniversary', icon:'rings',\n    grad:['#5A6BC4','#37469B'], tint:'linear-gradient(150deg, rgba(90,107,196,0.30), rgba(55,70,155,0.08))' },\n  { key:'marriage', label:'Marriage Anniversary', icon:'dove',\n    grad:['#B96D8E','#7D3F63'], tint:'linear-gradient(150deg, rgba(185,109,142,0.28), rgba(125,63,99,0.08))' },\n  { key:'baptism', label:'Baptism Anniversary', icon:'cross',\n    grad:['#4FA6A6','#2E7A7A'], tint:'linear-gradient(150deg, rgba(79,166,166,0.28), rgba(46,122,122,0.08))' },\n];\n\nconst MEMBERS = window.INITIAL_MEMBERS || [];\n\nconst VERSES = {\n  birthday:[\n    {ref:'Jeremiah 29:11', text:'For I know the plans I have for you, plans to prosper you and not to harm you, plans to give you hope and a future.'},\n    {ref:'Psalm 20:4', text:'May He give you the desire of your heart and make all your plans succeed.'},\n    {ref:'Numbers 6:24–26', text:'The Lord bless you and keep you; the Lord make His face shine upon you and be gracious to you.'},\n  ],\n  wedding:[\n    {ref:'Ecclesiastes 4:9–12', text:'Two are better than one, for a cord of three strands is not quickly broken.'},\n    {ref:'Ephesians 5:25', text:'Husbands, love your wives, just as Christ loved the church and gave Himself for her.'},\n    {ref:'1 Corinthians 13:4–7', text:'Love is patient, love is kind. It always protects, always trusts, always hopes, always perseveres.'},\n  ],\n  marriage:[\n    {ref:'Ecclesiastes 4:9–12', text:'Two are better than one, for a cord of three strands is not quickly broken.'},\n    {ref:'Ephesians 5:25', text:'Husbands, love your wives, just as Christ loved the church and gave Himself for her.'},\n    {ref:'1 Corinthians 13:4–7', text:'Love is patient, love is kind. It always protects, always trusts, always hopes, always perseveres.'},\n  ],\n  baptism:[\n    {ref:'Matthew 28:19', text:'Go and make disciples of all nations, baptizing them in the name of the Father, the Son, and the Holy Spirit.'},\n    {ref:'Romans 6:4', text:'We were buried with Him through baptism into death, so we too may walk in newness of life.'},\n    {ref:'Galatians 3:27', text:'For all of you who were baptized into Christ have clothed yourselves with Christ.'},\n  ],\n};\n\nconst THEMES = [\n  {key:'floral', name:'Floral Celebration', c:['#E7C767','#BE9A3A']},\n  {key:'golden', name:'Golden Blessings', c:['#F3D98B','#B4842A']},\n  {key:'royal', name:'Royal Blue', c:['#5A6BC4','#1E2A63']},\n  {key:'worship', name:'Church Worship', c:['#8A6FBF','#3D2C6B']},\n  {key:'white', name:'Elegant White', c:['#FDFBF6','#E4DAC2']},\n  {key:'balloons', name:'Balloons', c:['#F09A9A','#E7C767']},\n  {key:'minimal', name:'Minimal Modern', c:['#DCD6C8','#9C9483']},\n  {key:'cross', name:'Cross & Bible', c:['#4FA6A6','#1E2A63']},\n  {key:'family', name:'Family Celebration', c:['#E39A6B','#BE9A3A']},\n  {key:'children', name:\"Children's Theme\", c:['#7BC9E0','#F3D98B']},\n];\n\nconst AVATAR_PALETTES = [\n  ['#37469B','#5A6BC4'], ['#BE9A3A','#E7C767'], ['#7D3F63','#B96D8E'],\n  ['#2E7A7A','#4FA6A6'], ['#8A6FBF','#B79BE0'], ['#C4794A','#E3A16E'],\n];\n\n/* ============================= ICONS ============================= */\nconst ICONS = {\n  cake:`<svg class=\"glyph\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21h18\"/><path d=\"M5 21v-7a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v7\"/><path d=\"M12 12V8\"/><path d=\"M8 12V9\"/><path d=\"M16 12V9\"/><path d=\"M12 5a1.2 1.2 0 1 0 0-3 1.2 1.2 0 0 0 0 3Z\"/><path d=\"M8 6a1 1 0 1 0 0-2 1 1 0 0 0 0 2Z\"/><path d=\"M16 6a1 1 0 1 0 0-2 1 1 0 0 0 0 2Z\"/></svg>`,\n  rings:`<svg class=\"glyph\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><circle cx=\"9\" cy=\"14\" r=\"5\"/><circle cx=\"15\" cy=\"14\" r=\"5\"/><path d=\"M12 4l1.6 3.2L17 8l-2.4 2.2.6 3.3L12 12l-3.2 1.5.6-3.3L7 8l3.4-.8Z\" stroke-linejoin=\"round\"/></svg>`,\n  dove:`<svg class=\"glyph\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 21c-4-1-7-4-7-8a5 5 0 0 1 9-3\"/><path d=\"M12 21c4-1 7-4 7-8a5 5 0 0 0-9-3\"/><path d=\"M12 10V4\"/><path d=\"M9 5l3-2 3 2\"/></svg>`,\n  cross:`<svg class=\"glyph\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3v18\"/><path d=\"M7 8h10\"/></svg>`,\n  chevronRight:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 18l6-6-6-6\"/></svg>`,\n  whatsapp:`<svg viewBox=\"0 0 24 24\" fill=\"currentColor\" stroke=\"none\"><path d=\"M12 2a10 10 0 0 0-8.6 15.1L2 22l5.1-1.3A10 10 0 1 0 12 2Zm0 18.2a8.2 8.2 0 0 1-4.2-1.1l-.3-.2-3 .8.8-2.9-.2-.3A8.2 8.2 0 1 1 12 20.2Zm4.5-6.1c-.2-.1-1.5-.7-1.7-.8-.2-.1-.4-.1-.6.1-.2.2-.7.8-.8 1-.2.2-.3.2-.5.1-.2-.1-1-.4-1.9-1.2-.7-.6-1.2-1.4-1.3-1.6-.1-.2 0-.4.1-.5.1-.1.2-.3.4-.4.1-.2.2-.3.2-.5.1-.2 0-.4 0-.5 0-.1-.6-1.5-.8-2-.2-.5-.4-.4-.6-.4h-.5c-.2 0-.5.1-.7.3-.2.2-1 1-1 2.3 0 1.4 1 2.7 1.1 2.9.1.2 2 3 4.8 4.3.7.3 1.2.5 1.6.6.7.2 1.3.2 1.8.1.5-.1 1.5-.6 1.8-1.2.2-.6.2-1.1.1-1.2-.1-.2-.2-.2-.4-.3Z\"/></svg>`,\n  gift:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M20 12v9H4v-9\"/><path d=\"M2 7h20v5H2z\"/><path d=\"M12 22V7\"/><path d=\"M12 7H7.5a2.5 2.5 0 1 1 0-5C10 2 12 7 12 7Z\"/><path d=\"M12 7h4.5a2.5 2.5 0 1 0 0-5C14 2 12 7 12 7Z\"/></svg>`,\n  search:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.3-4.3\"/></svg>`,\n  sliders:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M4 21v-7\"/><path d=\"M4 10V3\"/><path d=\"M12 21v-9\"/><path d=\"M12 8V3\"/><path d=\"M20 21v-5\"/><path d=\"M20 12V3\"/><circle cx=\"4\" cy=\"13\" r=\"2\"/><circle cx=\"12\" cy=\"10\" r=\"2\"/><circle cx=\"20\" cy=\"14\" r=\"2\"/></svg>`,\n  book:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M4 4.5A2.5 2.5 0 0 1 6.5 2H20v17H6.5A2.5 2.5 0 0 0 4 21.5V4.5Z\"/><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"/></svg>`,\n  upload:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 16V4\"/><path d=\"m7 9 5-5 5 5\"/><path d=\"M4 16v3a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-3\"/></svg>`,\n  photo:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"3\"/><circle cx=\"9\" cy=\"9\" r=\"2\"/><path d=\"m21 15-5-5L5 21\"/></svg>`,\n  eye:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>`,\n  edit:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z\"/></svg>`,\n  check:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6 9 17l-5-5\"/></svg>`,\n  candle:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 21h6\"/><path d=\"M12 21v-6\"/><path d=\"M8 15a4 4 0 0 1 8 0c0 2-2 3-4 3s-4-1-4-3Z\"/><path d=\"M12 9V4\"/><path d=\"M12 4c1 0 1.5-1 .8-1.8C12.4 1.6 12 1 12 1s-.4.6-.8 1.2C10.5 3 11 4 12 4Z\"/></svg>`,\n  house:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m3 10 9-7 9 7\"/><path d=\"M5 9v11h14V9\"/></svg>`,\n  calendar:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"4.5\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M3 9.5h18\"/><path d=\"M8 2.5v4\"/><path d=\"M16 2.5v4\"/></svg>`,\n};\n\nfunction roseSVG(colors, seed=0){\n  const [c1,c2] = colors;\n  const id = 'g'+seed;\n  return `<svg class=\"rose-bg\" viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\">\n    <defs><radialGradient id=\"${id}\" cx=\"50%\" cy=\"50%\" r=\"60%\">\n      <stop offset=\"0%\" stop-color=\"${c1}\"/><stop offset=\"100%\" stop-color=\"${c2}\"/>\n    </radialGradient></defs>\n    <circle cx=\"50\" cy=\"50\" r=\"48\" fill=\"url(#${id})\"/>\n    <g fill=\"none\" stroke=\"#fff\" stroke-opacity=\"0.35\" stroke-width=\"1\">\n      <circle cx=\"50\" cy=\"50\" r=\"36\"/>\n      ${Array.from({length:8}).map((_,i)=>{\n        const a = (i*45)*Math.PI/180;\n        const x = 50+34*Math.cos(a), y = 50+34*Math.sin(a);\n        return `<circle cx=\"${x.toFixed(1)}\" cy=\"${y.toFixed(1)}\" r=\"9\"/>`;\n      }).join('')}\n    </g>\n  </svg>`;\n}\n\n/* ============================= STATE ============================= */\nconst state = {\n  stack:['dashboard'],\n  category:null,\n  filter:'upcoming',\n  search:'',\n  sort:'nearest',\n  showFilters:false,\n  ministry:'all', family:'all', age:'all', year:'all',\n  memberId:null,\n  theme:null,\n  verse:null,\n  image:null,\n  message:'',\n  sender:'Grace Community Church',\n};\n\nfunction go(screen, patch={}){\n  Object.assign(state, patch);\n  state.stack.push(screen);\n  render();\n  scrollTop();\n}\nfunction back(){\n  if(state.stack.length>1){ state.stack.pop(); render(); scrollTop(); }\n}\nfunction resetTo(screen){\n  state.stack = [screen];\n  render(); scrollTop();\n}\nfunction scrollTop(){ document.getElementById('screenRoot').scrollTop = 0; }\nfunction current(){ return state.stack[state.stack.length-1]; }\n\nfunction toast(msg){\n  const t = document.getElementById('toast');\n  t.textContent = msg;\n  t.classList.add('show');\n  clearTimeout(window.__toastTimer);\n  window.__toastTimer = setTimeout(()=>t.classList.remove('show'), 2200);\n}\n\n/* ============================= DATE HELPERS ============================= */\nfunction occurrenceThisYear(m){\n  return new Date(TODAY.getFullYear(), m.month-1, m.day);\n}\nfunction nextOccurrence(m){\n  let d = occurrenceThisYear(m);\n  if(d < stripTime(TODAY)) d = new Date(TODAY.getFullYear()+1, m.month-1, m.day);\n  return d;\n}\nfunction stripTime(d){ return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }\nfunction daysUntil(m){\n  const diff = nextOccurrence(m) - stripTime(TODAY);\n  return Math.round(diff/86400000);\n}\nfunction isToday(m){ return m.month===TODAY.getMonth()+1 && m.day===TODAY.getDate(); }\nfunction isPastThisYear(m){ return occurrenceThisYear(m) < stripTime(TODAY) && !isToday(m); }\nfunction isThisWeek(m){ const d = daysUntil(m); return d>=0 && d<=7; }\nfunction isThisMonth(m){ return m.month === TODAY.getMonth()+1; }\nfunction formatDate(m){\n  const names=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];\n  return `${names[m.month-1]} ${m.day}`;\n}\nfunction yearsLabel(cat, refYear){\n  if(cat==='birthday') return `${TODAY.getFullYear()-refYear} yrs`;\n  return `${TODAY.getFullYear()-refYear} yrs together`;\n}\nfunction initials(name){\n  const clean = name.split('&')[0].trim();\n  const parts = clean.split(' ');\n  return (parts[0][0]+(parts[1]?parts[1][0]:'')).toUpperCase();\n}\nfunction paletteFor(id){\n  let h=0; for(const c of id) h += c.charCodeAt(0);\n  return AVATAR_PALETTES[h % AVATAR_PALETTES.length];\n}\nfunction avatarStyle(id){\n  const [c1,c2] = paletteFor(id);\n  return `background:linear-gradient(135deg, ${c1}, ${c2});`;\n}\nfunction catMeta(key){ return CATEGORIES.find(c=>c.key===key); }\n\n/* ============================= FILTER LOGIC ============================= */\nfunction filteredMembers(){\n  let list = MEMBERS.filter(m=>m.category===state.category);\n\n  if(state.search.trim()){\n    const q = state.search.trim().toLowerCase();\n    list = list.filter(m=>m.name.toLowerCase().includes(q));\n  }\n  if(state.ministry !== 'all') list = list.filter(m=>m.ministry===state.ministry);\n  if(state.family !== 'all') list = list.filter(m=>m.family===state.family);\n\n  if(state.category==='birthday' && state.age!=='all'){\n    list = list.filter(m=>{\n      const age = TODAY.getFullYear()-m.refYear;\n      if(state.age==='u18') return age<18;\n      if(state.age==='18-40') return age>=18 && age<=40;\n      if(state.age==='41-60') return age>=41 && age<=60;\n      if(state.age==='60p') return age>60;\n      return true;\n    });\n  }\n  if((state.category==='wedding'||state.category==='marriage') && state.year!=='all'){\n    list = list.filter(m=>String(m.refYear)===state.year);\n  }\n  if(state.category==='baptism' && state.year!=='all'){\n    list = list.filter(m=>String(m.refYear)===state.year);\n  }\n\n  switch(state.filter){\n    case 'today': list = list.filter(isToday); break;\n    case 'upcoming': list = list.filter(m=>!isPastThisYear(m)); break;\n    case 'week': list = list.filter(isThisWeek); break;\n    case 'month': list = list.filter(isThisMonth); break;\n    case 'past': list = list.filter(isPastThisYear); break;\n    case 'all': default: break;\n  }\n\n  if(state.sort==='nearest'){\n    list = [...list].sort((a,b)=>daysUntil(a)-daysUntil(b));\n  } else {\n    list = [...list].sort((a,b)=>a.name.localeCompare(b.name));\n  }\n  return list;\n}\n\n/* ============================= RENDER: DASHBOARD ============================= */\nfunction renderDashboard(){\n  const total = MEMBERS.length;\n  const todays = MEMBERS.filter(isToday).length;\n  const thisWeek = MEMBERS.filter(isThisWeek).length;\n\n  const cards = CATEGORIES.map(c=>{\n    const count = MEMBERS.filter(m=>m.category===c.key).length;\n    const soon = MEMBERS.filter(m=>m.category===c.key && isThisWeek(m)).length;\n    return `\n    <div class=\"cat-card\" data-action=\"open-category\" data-cat=\"${c.key}\">\n      <div class=\"tint\" style=\"background:${c.tint}\"></div>\n      <div class=\"content\">\n        <div class=\"rose-icon-frame\">${roseSVG(c.grad, c.key)}<div class=\"glyph\" style=\"color:#fff\">${ICONS[c.icon]}</div></div>\n        <p class=\"cat-name\">${c.label}</p>\n        <p class=\"cat-count\"><b>${count}</b> members ${soon?`· <span style=\"color:${c.grad[1]}\">${soon} this week</span>`:''}</p>\n      </div>\n    </div>`;\n  }).join('');\n\n  return `\n    <div class=\"hero-card\">\n      ${roseHeroBg()}\n      <div class=\"hero-eyebrow\">This Season</div>\n      <h2 class=\"hero-title\">Celebrations<br/>worth remembering</h2>\n      <p class=\"hero-sub\">Browse birthdays, anniversaries and baptisms across the parish, and prepare a beautiful wish in moments.</p>\n      <div class=\"hero-stats\">\n        <div class=\"hero-stat\"><b>${total}</b><span>TOTAL RECORDS</span></div>\n        <div class=\"hero-stat\"><b>${todays}</b><span>TODAY</span></div>\n        <div class=\"hero-stat\"><b>${thisWeek}</b><span>THIS WEEK</span></div>\n      </div>\n    </div>\n    <div class=\"section-label\">Celebration Categories</div>\n    <div class=\"cat-grid\">${cards}</div>\n    <div class=\"footer-note\">Grace Community Church · Celebrations Module</div>\n  `;\n}\nfunction roseHeroBg(){\n  return `<svg style=\"position:absolute; left:-30px; bottom:-40px; width:160px; opacity:0.18;\" viewBox=\"0 0 100 100\"><g fill=\"none\" stroke=\"#fff\" stroke-width=\"1\"><circle cx=\"50\" cy=\"50\" r=\"46\"/><circle cx=\"50\" cy=\"50\" r=\"32\"/><circle cx=\"50\" cy=\"50\" r=\"18\"/></g></svg>`;\n}\n\n/* ============================= RENDER: LIST ============================= */\nconst FILTER_TABS = [\n  {key:'today', label:'Today'},\n  {key:'upcoming', label:'Upcoming'},\n  {key:'week', label:'This Week'},\n  {key:'month', label:'This Month'},\n  {key:'past', label:'Past'},\n  {key:'all', label:'All'},\n];\n\nfunction uniqueValues(list, field){\n  return [...new Set(list.map(m=>m[field]))].sort();\n}\n\nfunction renderList(){\n  const cat = catMeta(state.category);\n  const allInCat = MEMBERS.filter(m=>m.category===state.category);\n  const ministries = uniqueValues(allInCat,'ministry');\n  const families = uniqueValues(allInCat,'family');\n  const years = uniqueValues(allInCat,'refYear');\n  const list = filteredMembers();\n\n  const tabs = FILTER_TABS.map(t=>`\n    <div class=\"filter-chip ${state.filter===t.key?'active':''}\" data-action=\"set-filter\" data-filter=\"${t.key}\">${t.label}</div>\n  `).join('');\n\n  let extraFilterField = '';\n  if(state.category==='birthday'){\n    extraFilterField = `\n    <div class=\"field\"><label>Age</label>\n      <select id=\"ageSelect\">\n        <option value=\"all\">All ages</option>\n        <option value=\"u18\">Under 18</option>\n        <option value=\"18-40\">18–40</option>\n        <option value=\"41-60\">41–60</option>\n        <option value=\"60p\">60+</option>\n      </select>\n    </div>`;\n  } else if(state.category==='wedding' || state.category==='marriage'){\n    extraFilterField = `\n    <div class=\"field\"><label>Wedding Year</label>\n      <select id=\"yearSelect\"><option value=\"all\">All years</option>${years.map(y=>`<option value=\"${y}\">${y}</option>`).join('')}</select>\n    </div>`;\n  } else if(state.category==='baptism'){\n    extraFilterField = `\n    <div class=\"field\"><label>Baptism Year</label>\n      <select id=\"yearSelect\"><option value=\"all\">All years</option>${years.map(y=>`<option value=\"${y}\">${y}</option>`).join('')}</select>\n    </div>`;\n  }\n\n  const filtersPanel = state.showFilters ? `\n    <div class=\"filters-panel\">\n      <div class=\"field\"><label>Ministry</label>\n        <select id=\"ministrySelect\"><option value=\"all\">All ministries</option>${ministries.map(v=>`<option value=\"${v}\">${v}</option>`).join('')}</select>\n      </div>\n      <div class=\"field\"><label>Family</label>\n        <select id=\"familySelect\"><option value=\"all\">All families</option>${families.map(v=>`<option value=\"${v}\">${v}</option>`).join('')}</select>\n      </div>\n      ${extraFilterField}\n      <div class=\"field\"><label>Sort by</label>\n        <select id=\"sortSelect\">\n          <option value=\"nearest\">Nearest celebration</option>\n          <option value=\"alpha\">Alphabetical</option>\n        </select>\n      </div>\n    </div>\n  ` : '';\n\n  const cards = list.length ? list.map(m=>memberCardHTML(m)).join('') : emptyStateHTML();\n\n  return `\n    <div class=\"section-label\" style=\"margin-top:6px;\">${cat.label}</div>\n    <div class=\"filter-scroll\">${tabs}</div>\n    <div class=\"search-row\">\n      <div class=\"search-box\">${ICONS.search}<input id=\"searchInput\" type=\"text\" placeholder=\"Search by name…\" value=\"${state.search.replace(/\"/g,'&quot;')}\"/></div>\n      <div class=\"icon-btn ${state.showFilters?'active-dot':''}\" data-action=\"toggle-filters\">${ICONS.sliders}</div>\n    </div>\n    ${filtersPanel}\n    <div class=\"result-count\">${list.length} member${list.length===1?'':'s'} found</div>\n    ${cards}\n  `;\n}\n\nfunction memberCardHTML(m){\n  const cat = catMeta(m.category);\n  const dateLbl = formatDate(m);\n  const yrsLbl = yearsLabel(m.category, m.refYear);\n  return `\n  <div class=\"member-card\" data-action=\"open-member\" data-id=\"${m.id}\">\n    <div class=\"avatar\" style=\"${avatarStyle(m.id)}\">${initials(m.name)}</div>\n    <div class=\"mc-info\">\n      <p class=\"mc-name\">${m.name}</p>\n      <div class=\"mc-meta\">\n        <span class=\"badge\" style=\"background:linear-gradient(120deg, ${cat.grad[0]}, ${cat.grad[1]})\">${cat.label.replace(' Anniversary','')}</span>\n        <span class=\"mc-date\">${dateLbl}</span>\n        <span>· ${yrsLbl}</span>\n      </div>\n    </div>\n    <div class=\"mc-actions\">\n      <div class=\"mini-btn whatsapp\" data-action=\"whatsapp-quick\" data-id=\"${m.id}\" title=\"WhatsApp\">${ICONS.whatsapp}</div>\n      <div class=\"mini-btn wish\" data-action=\"prepare-wish\" data-id=\"${m.id}\" title=\"Prepare Wish\">${ICONS.gift}</div>\n    </div>\n  </div>`;\n}\n\nfunction emptyStateHTML(){\n  return `\n  <div class=\"empty-state\">\n    ${ICONS.candle}\n    <p>No celebrations match these filters yet.<br/>Try widening the date range or clearing a filter.</p>\n  </div>`;\n}\n\n/* ============================= RENDER: DETAILS ============================= */\nfunction renderDetails(){\n  const m = MEMBERS.find(x=>x.id===state.memberId);\n  const cat = catMeta(m.category);\n  return `\n  <div class=\"details-hero\">\n    <div class=\"avatar lg\" style=\"${avatarStyle(m.id)}\">${initials(m.name)}</div>\n    <span class=\"cat-tag\" style=\"background:linear-gradient(120deg, ${cat.grad[0]}, ${cat.grad[1]})\">${cat.label}</span>\n    <h2>${m.name}</h2>\n  </div>\n  <div class=\"info-grid\">\n    <div class=\"info-tile\"><div class=\"lbl\">Celebration Date</div><div class=\"val\">${formatDate(m)}</div></div>\n    <div class=\"info-tile\"><div class=\"lbl\">${m.category==='birthday'?'Turning':'Years Completed'}</div><div class=\"val\">${TODAY.getFullYear()-m.refYear} ${m.category==='birthday'?'yrs old':'yrs'}</div></div>\n    <div class=\"info-tile\"><div class=\"lbl\">Ministry</div><div class=\"val\">${m.ministry}</div></div>\n    <div class=\"info-tile\"><div class=\"lbl\">Family</div><div class=\"val\">${m.family}</div></div>\n    <div class=\"info-tile full\"><div class=\"lbl\">WhatsApp Number</div><div class=\"val\">${m.phone}</div></div>\n  </div>\n  <button class=\"primary-btn\" data-action=\"prepare-wish\" data-id=\"${m.id}\">${ICONS.gift} Prepare Wish</button>\n  <button class=\"primary-btn outline\" data-action=\"whatsapp-quick\" data-id=\"${m.id}\" style=\"margin-top:10px;\">${ICONS.whatsapp} Message on WhatsApp</button>\n  `;\n}\n\n/* ============================= RENDER: CUSTOMIZE ============================= */\nfunction defaultMessage(m){\n  const cat = m.category;\n  if(cat==='birthday') return `Dear ${m.name.split(' ')[0]}, wishing you a joy-filled birthday surrounded by God's love and grace. May this new year of life be your best yet!`;\n  if(cat==='wedding') return `Congratulations ${m.name} on ${TODAY.getFullYear()-m.refYear} beautiful years of marriage! May your love continue to grow deeper, rooted in faith.`;\n  if(cat==='marriage') return `Celebrating ${m.name} today! ${TODAY.getFullYear()-m.refYear} years of covenant love — may the Lord continue to bless your journey together.`;\n  return `Celebrating ${m.name}'s baptism anniversary today — ${TODAY.getFullYear()-m.refYear} years walking in the light of Christ. God bless you always!`;\n}\n\nfunction renderCustomize(){\n  const m = MEMBERS.find(x=>x.id===state.memberId);\n  if(!state.message) state.message = defaultMessage(m);\n  if(!state.verse) state.verse = VERSES[m.category][0];\n  const theme = state.theme ? THEMES.find(t=>t.key===state.theme) : null;\n\n  return `\n  <div class=\"section-label\" style=\"margin-top:6px;\">Personalize the Greeting</div>\n  <p style=\"font-size:12.5px; color:var(--ink-soft); margin:-6px 2px 16px 2px;\">for <b style=\"color:var(--ink)\">${m.name}</b></p>\n\n  <div class=\"option-row\" data-action=\"open-theme\">\n    <div class=\"left\">\n      <div class=\"ic\">${ICONS.eye}</div>\n      <div class=\"txt\"><div class=\"t1\">Choose Theme</div><div class=\"t2\">${theme?theme.name:'Select a greeting style'}</div></div>\n    </div>\n    <div class=\"chevron\">${ICONS.chevronRight}</div>\n  </div>\n\n  <div class=\"option-row\" data-action=\"open-upload\">\n    <div class=\"left\">\n      <div class=\"ic\">${ICONS.photo}</div>\n      <div class=\"txt\"><div class=\"t1\">Photo</div><div class=\"t2\">${state.image ? state.image : \"Use member's profile picture\"}</div></div>\n    </div>\n    <div class=\"chevron\">${ICONS.chevronRight}</div>\n  </div>\n\n  <div class=\"option-row\" data-action=\"open-verse\">\n    <div class=\"left\">\n      <div class=\"ic\">${ICONS.book}</div>\n      <div class=\"txt\"><div class=\"t1\">Bible Verse</div><div class=\"t2\">${state.verse.ref}</div></div>\n    </div>\n    <div class=\"chevron\">${ICONS.chevronRight}</div>\n  </div>\n\n  <div class=\"divider-label\">Greeting Message</div>\n  <textarea class=\"msg-input\" id=\"msgInput\">${state.message}</textarea>\n\n  <button class=\"primary-btn\" data-action=\"preview\">${ICONS.eye} Preview Greeting</button>\n  `;\n}\n\n/* ============================= RENDER: THEME ============================= */\nfunction renderTheme(){\n  const cards = THEMES.map(t=>`\n    <div class=\"theme-card ${state.theme===t.key?'selected':''}\" data-action=\"select-theme\" data-theme=\"${t.key}\">\n      <div class=\"theme-preview\">\n        <svg viewBox=\"0 0 200 130\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs><linearGradient id=\"tg-${t.key}\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n            <stop offset=\"0%\" stop-color=\"${t.c[0]}\"/><stop offset=\"100%\" stop-color=\"${t.c[1]}\"/>\n          </linearGradient></defs>\n          <rect width=\"200\" height=\"130\" fill=\"url(#tg-${t.key})\"/>\n          <circle cx=\"170\" cy=\"20\" r=\"30\" fill=\"#fff\" opacity=\"0.12\"/>\n          <circle cx=\"20\" cy=\"115\" r=\"40\" fill=\"#fff\" opacity=\"0.10\"/>\n        </svg>\n      </div>\n      <div class=\"theme-label\">${t.name}</div>\n      ${state.theme===t.key?`<div class=\"theme-check\">${ICONS.check}</div>`:''}\n    </div>\n  `).join('');\n  return `\n  <div class=\"section-label\" style=\"margin-top:6px;\">Choose Celebration Theme</div>\n  <div class=\"theme-grid\">${cards}</div>\n  `;\n}\n\n/* ============================= RENDER: VERSE ============================= */\nfunction renderVerse(){\n  const m = MEMBERS.find(x=>x.id===state.memberId);\n  const verses = VERSES[m.category];\n  const cards = verses.map(v=>`\n    <div class=\"verse-card ${state.verse && state.verse.ref===v.ref?'selected':''}\" data-action=\"select-verse\" data-verse=\"${v.ref}\">\n      <p class=\"verse-text\">\"${v.text}\"</p>\n      <p class=\"verse-ref\">${v.ref}</p>\n    </div>\n  `).join('');\n  return `\n  <div class=\"section-label\" style=\"margin-top:6px;\">Select Bible Verse</div>\n  <p style=\"font-size:12px; color:var(--ink-soft); margin:-6px 2px 16px 2px;\">Suggested for ${catMeta(m.category).label.toLowerCase()}</p>\n  ${cards}\n  `;\n}\n\n/* ============================= RENDER: UPLOAD ============================= */\nfunction renderUpload(){\n  const m = MEMBERS.find(x=>x.id===state.memberId);\n  const samples = ['#E7C767,#BE9A3A','#5A6BC4,#37469B','#4FA6A6,#2E7A7A','#B96D8E,#7D3F63','#8A6FBF,#B79BE0','#C4794A,#E3A16E'];\n  return `\n  <div class=\"section-label\" style=\"margin-top:6px;\">Upload Image</div>\n  <div class=\"upload-zone\" data-action=\"upload-custom\">\n    ${ICONS.upload}\n    <p>Tap to upload a custom photo</p>\n    <p class=\"hint\">JPG or PNG, up to 10MB</p>\n  </div>\n  <button class=\"primary-btn outline\" data-action=\"use-profile-photo\" data-id=\"${m.id}\" style=\"margin-top:14px;\">${ICONS.photo} Use ${m.name.split(' ')[0]}'s Profile Picture</button>\n  <div class=\"divider-label\">Or Choose a Sample</div>\n  <div class=\"sample-grid\">\n    ${samples.map((s,i)=>{\n      const [c1,c2]=s.split(',');\n      return `<div class=\"sample-thumb ${state.image==='Sample '+(i+1)?'selected':''}\" data-action=\"select-sample\" data-sample=\"${i+1}\">\n        <svg viewBox=\"0 0 60 60\"><defs><linearGradient id=\"sm-${i}\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0%\" stop-color=\"${c1}\"/><stop offset=\"100%\" stop-color=\"${c2}\"/></linearGradient></defs><rect width=\"60\" height=\"60\" fill=\"url(#sm-${i})\"/></svg>\n      </div>`;\n    }).join('')}\n  </div>\n  `;\n}\n\n/* ============================= RENDER: GREETING PREVIEW ============================= */\nfunction greetingSVG(theme){\n  const t = THEMES.find(x=>x.key===theme) || THEMES[2];\n  return `<svg viewBox=\"0 0 400 500\" xmlns=\"http://www.w3.org/2000/svg\">\n    <defs><linearGradient id=\"pg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"${t.c[0]}\"/><stop offset=\"100%\" stop-color=\"${t.c[1]}\"/>\n    </linearGradient></defs>\n    <rect width=\"400\" height=\"500\" fill=\"url(#pg)\"/>\n    <g fill=\"#fff\" opacity=\"0.10\">\n      <circle cx=\"60\" cy=\"60\" r=\"70\"/><circle cx=\"360\" cy=\"440\" r=\"90\"/><circle cx=\"370\" cy=\"60\" r=\"40\"/>\n    </g>\n    <g fill=\"none\" stroke=\"#fff\" stroke-opacity=\"0.25\" stroke-width=\"1.5\">\n      <circle cx=\"200\" cy=\"250\" r=\"150\"/><circle cx=\"200\" cy=\"250\" r=\"110\"/>\n    </g>\n  </svg>`;\n}\n\nfunction renderPreview(){\n  const m = MEMBERS.find(x=>x.id===state.memberId);\n  const cat = catMeta(m.category);\n  return `\n  <div class=\"section-label\" style=\"margin-top:6px;\">Greeting Preview</div>\n  <div class=\"greeting-frame\">\n    ${greetingSVG(state.theme)}\n    <div class=\"greeting-overlay\">\n      <div class=\"g-crest\">Grace Community Church</div>\n      <div class=\"g-title\">${cat.label}</div>\n      <div class=\"g-name\">${m.name}</div>\n      <p class=\"g-msg\">${state.message}</p>\n      <p class=\"g-verse\">\"${state.verse.text.length>90?state.verse.text.slice(0,90)+'…':state.verse.text}\"<br/>— ${state.verse.ref}</p>\n      <div class=\"g-sender\">Sent with love, ${state.sender}</div>\n    </div>\n  </div>\n  <div class=\"secondary-row\" style=\"margin-top:16px;\">\n    <button class=\"primary-btn outline\" data-action=\"edit-message\">${ICONS.edit} Edit</button>\n    <button class=\"primary-btn royal\" data-action=\"open-whatsapp\">${ICONS.whatsapp} Continue</button>\n  </div>\n  `;\n}\n\n/* ============================= RENDER: WHATSAPP ============================= */\nfunction renderWhatsapp(){\n  const m = MEMBERS.find(x=>x.id===state.memberId);\n  const cat = catMeta(m.category);\n  return `\n  <div class=\"section-label\" style=\"margin-top:6px;\">WhatsApp Preview</div>\n  <div class=\"wa-header\">\n    <div class=\"avatar\" style=\"${avatarStyle(m.id)}\">${initials(m.name)}</div>\n    <div><div class=\"nm\">${m.name}</div><div class=\"st\">${m.phone}</div></div>\n  </div>\n  <div class=\"wa-body\">\n    <div class=\"wa-bubble\">\n      ${greetingSVG(state.theme)}\n      <div class=\"wa-caption\">${state.message}</div>\n      <div class=\"wa-verse\">\"${state.verse.ref}\"</div>\n      <div class=\"wa-time\">9:41 AM ✓✓</div>\n    </div>\n  </div>\n  <div class=\"secondary-row\" style=\"margin-top:16px;\">\n    <button class=\"primary-btn outline\" data-action=\"edit-message\">${ICONS.edit} Edit Message</button>\n    <button class=\"primary-btn\" data-action=\"send-whatsapp\">${ICONS.whatsapp} Send via WhatsApp</button>\n  </div>\n  `;\n}\n\n/* ============================= RENDER: CONFIRM ============================= */\nfunction renderConfirm(){\n  const m = MEMBERS.find(x=>x.id===state.memberId);\n  return `\n  <div class=\"confirm-wrap\">\n    <div class=\"confirm-check\">${ICONS.check}</div>\n    <h2>Greeting Sent!</h2>\n    <p>Your ${catMeta(m.category).label.toLowerCase()} wish for <b>${m.name}</b> has been sent via WhatsApp.</p>\n    <button class=\"primary-btn royal\" style=\"max-width:220px;\" data-action=\"go-dashboard\">${ICONS.house} Back to Celebrations</button>\n  </div>\n  `;\n}\n\n/* ============================= MASTER RENDER ============================= */\nfunction render(){\n  const screen = current();\n  const root = document.getElementById('screenRoot');\n  const backBtn = document.getElementById('backBtn');\n  const titleEl = document.getElementById('appTitle');\n  const eyebrowEl = document.getElementById('appEyebrow');\n\n  backBtn.classList.toggle('hidden', state.stack.length<=1);\n\n  const titles = {\n    dashboard:['Church Companion','Celebrations'],\n    list:['Celebrations', state.category?catMeta(state.category).label:''],\n    details:['Celebration','Member Details'],\n    customize:['Prepare Wish','Personalize'],\n    theme:['Prepare Wish','Choose Theme'],\n    verse:['Prepare Wish','Bible Verse'],\n    upload:['Prepare Wish','Upload Photo'],\n    preview:['Prepare Wish','Preview'],\n    whatsapp:['Prepare Wish','WhatsApp'],\n    confirm:['Celebrations','Sent'],\n  };\n  const [eb,ti] = titles[screen] || ['Church Companion','Celebrations'];\n  eyebrowEl.textContent = eb;\n  titleEl.textContent = ti;\n\n  let html = '';\n  switch(screen){\n    case 'dashboard': html = renderDashboard(); break;\n    case 'list': html = renderList(); break;\n    case 'details': html = renderDetails(); break;\n    case 'customize': html = renderCustomize(); break;\n    case 'theme': html = renderTheme(); break;\n    case 'verse': html = renderVerse(); break;\n    case 'upload': html = renderUpload(); break;\n    case 'preview': html = renderPreview(); break;\n    case 'whatsapp': html = renderWhatsapp(); break;\n    case 'confirm': html = renderConfirm(); break;\n  }\n  root.innerHTML = `<div class=\"screen\">${html}</div>`;\n  wireDynamicInputs(screen);\n}\n\nfunction wireDynamicInputs(screen){\n  if(screen==='list'){\n    const s = document.getElementById('searchInput');\n    if(s) s.addEventListener('input', e=>{ state.search = e.target.value; renderListOnly(); });\n    const ms = document.getElementById('ministrySelect');\n    if(ms){ ms.value = state.ministry; ms.addEventListener('change', e=>{ state.ministry=e.target.value; renderListOnly(); }); }\n    const fs = document.getElementById('familySelect');\n    if(fs){ fs.value = state.family; fs.addEventListener('change', e=>{ state.family=e.target.value; renderListOnly(); }); }\n    const as = document.getElementById('ageSelect');\n    if(as){ as.value = state.age; as.addEventListener('change', e=>{ state.age=e.target.value; renderListOnly(); }); }\n    const ys = document.getElementById('yearSelect');\n    if(ys){ ys.value = state.year; ys.addEventListener('change', e=>{ state.year=e.target.value; renderListOnly(); }); }\n    const so = document.getElementById('sortSelect');\n    if(so){ so.value = state.sort; so.addEventListener('change', e=>{ state.sort=e.target.value; renderListOnly(); }); }\n  }\n  if(screen==='customize'){\n    const mi = document.getElementById('msgInput');\n    if(mi) mi.addEventListener('input', e=>{ state.message = e.target.value; });\n  }\n}\n\n// Lightweight re-render that preserves scroll & focus better for list filtering\nfunction renderListOnly(){\n  const root = document.getElementById('screenRoot');\n  root.innerHTML = `<div class=\"screen\">${renderList()}</div>`;\n  wireDynamicInputs('list');\n}\n\n/* ============================= ACTIONS ============================= */\ndocument.addEventListener('click', (e)=>{\n  const el = e.target.closest('[data-action]');\n  if(!el) return;\n  const a = el.dataset.action;\n\n  switch(a){\n    case 'back': back(); break;\n    case 'go-dashboard': resetTo('dashboard'); state.memberId=null; state.theme=null; state.verse=null; state.image=null; state.message=''; break;\n\n    case 'open-category':\n      state.category = el.dataset.cat;\n      state.filter='upcoming'; state.search=''; state.ministry='all'; state.family='all'; state.age='all'; state.year='all'; state.showFilters=false; state.sort='nearest';\n      go('list');\n      break;\n\n    case 'set-filter':\n      state.filter = el.dataset.filter;\n      renderListOnly();\n      break;\n\n    case 'toggle-filters':\n      state.showFilters = !state.showFilters;\n      renderListOnly();\n      break;\n\n    case 'open-member':\n      state.memberId = el.dataset.id;\n      go('details');\n      break;\n\n    case 'prepare-wish':\n      state.memberId = el.dataset.id;\n      state.theme=null; state.verse=null; state.image=null; state.message='';\n      go('customize');\n      break;\n\n    case 'whatsapp-quick': {\n      const m = MEMBERS.find(x=>x.id===el.dataset.id);\n      toast(`Opening WhatsApp chat with ${m.name.split(' ')[0]}…`);\n      break;\n    }\n\n    case 'open-theme': go('theme'); break;\n    case 'select-theme':\n      state.theme = el.dataset.theme;\n      toast('Theme applied');\n      back();\n      break;\n\n    case 'open-verse': go('verse'); break;\n    case 'select-verse': {\n      const m = MEMBERS.find(x=>x.id===state.memberId);\n      state.verse = VERSES[m.category].find(v=>v.ref===el.dataset.verse);\n      toast('Verse selected');\n      back();\n      break;\n    }\n\n    case 'open-upload': go('upload'); break;\n    case 'upload-custom':\n      state.image = 'Custom Photo.jpg';\n      toast('Image uploaded');\n      back();\n      break;\n    case 'use-profile-photo': {\n      const m = MEMBERS.find(x=>x.id===el.dataset.id);\n      state.image = `${m.name.split(' ')[0]}'s Profile Picture`;\n      toast('Using profile picture');\n      back();\n      break;\n    }\n    case 'select-sample':\n      state.image = 'Sample '+el.dataset.sample;\n      toast('Sample image selected');\n      back();\n      break;\n\n    case 'preview': go('preview'); break;\n    case 'edit-message':\n      while(state.stack.length>1 && current()!=='customize') state.stack.pop();\n      render(); scrollTop();\n      break;\n    case 'open-whatsapp': go('whatsapp'); break;\n\n    case 'send-whatsapp': \n  if (window.ReactNativeWebView) {\n    window.ReactNativeWebView.postMessage(JSON.stringify({ \n      type: 'SEND_WHATSAPP', \n      memberId: state.memberId, \n      message: state.message, \n      theme: state.theme, \n      verse: state.verse \n    }));\n  }\n  toast('Sending message...');\n  setTimeout(() => go('confirm'), 500);\n  break;\n  }\n});\n\n/* clock */\nfunction tickClock(){\n  const now = new Date();\n  const h = now.getHours()%12 || 12;\n  const mnt = String(now.getMinutes()).padStart(2,'0');\n  document.getElementById('clock').textContent = `${h}:${mnt}`;\n}\ntickClock(); setInterval(tickClock, 30000);\n\nrender();\n</script>\n</body>\n</html>\n";
